import{_ as a,C as r,o,c as l,a2 as e,E as s}from"./chunks/framework.BSaF8iZ6.js";const b=JSON.parse('{"title":"Plans & Subscriptions","description":"","frontmatter":{},"headers":[],"relativePath":"subscriptions/seller-subscription-management.md","filePath":"subscriptions/seller-subscription-management.md","lastUpdated":1789411447000}'),i={name:"subscriptions/seller-subscription-management.md"};function d(p,t,g,h,c,u){const n=r("ImagePopup");return o(),l("div",null,[t[0]||(t[0]=e('<h1 id="plans-subscriptions" tabindex="-1">Plans &amp; Subscriptions <a class="header-anchor" href="#plans-subscriptions" aria-label="Permalink to &quot;Plans &amp; Subscriptions&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span></div><p>Subscription plans let you charge sellers for selling on your marketplace. Each plan sets a price and a length, how many products and team members the seller can have, the commission you take, and what the seller can use in the Seller Panel.</p><p>Plans are off until you turn them on. With plans off, sellers sell without a plan and you earn through <a href="./../payments/commission-management">commission</a>.</p><h2 id="turn-on-plans" tabindex="-1">Turn on plans <a class="header-anchor" href="#turn-on-plans" aria-label="Permalink to &quot;Turn on plans&quot;">​</a></h2><p>Switch <strong>Subscription Plans</strong> on and enter your terms in <strong>Configure &gt;&gt; Marketplace &gt;&gt; General</strong>. See <a href="./../configuration/general#turn-on-subscription-plans">General settings</a>.</p><p><strong>Marketplace &gt;&gt; Subscription Plans</strong> then appears in the admin panel.</p><h2 id="create-a-plan" tabindex="-1">Create a plan <a class="header-anchor" href="#create-a-plan" aria-label="Permalink to &quot;Create a plan&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Subscription Plans &gt;&gt; Plans</strong>.</li><li>Click <strong>Add Plan</strong>.</li><li>Fill in the fields below. <strong>Name</strong>, <strong>Code</strong>, <strong>Price</strong>, <strong>Permissions</strong> and <strong>Position</strong> are required.</li><li>Switch <strong>Status</strong> on so sellers can see the plan.</li><li>Click <strong>Save</strong>.</li></ol>',9)),s(n,{src:"/images/seller-subscription-management/edit-plan.png",alt:"The plan form with its fields, open on a monthly plan"}),t[1]||(t[1]=e('<table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Name</strong> and <strong>Description</strong></td><td>The name is shown on the plan card. Sellers see the description when they open the plan.</td></tr><tr><td><strong>Code</strong></td><td>A unique code for the plan.</td></tr><tr><td><strong>Is Default</strong></td><td>Makes this the free plan. The <strong>Price</strong> field is hidden. Sellers are offered the free plan only until they have had a plan that became active.</td></tr><tr><td><strong>Price</strong></td><td>What the plan costs. It must be more than 0 unless <strong>Is Default</strong> is on.</td></tr><tr><td><strong>Permissions</strong></td><td><strong>All</strong> gives access to the whole Seller Panel. <strong>Custom</strong> shows a tree where you tick what the plan includes.</td></tr><tr><td><strong>Billing Cycle</strong></td><td><strong>Monthly</strong> or <strong>Yearly</strong>.</td></tr><tr><td><strong>Duration (days)</strong></td><td>How long the plan lasts. Leave it empty for 30 days on a monthly plan or 365 days on a yearly one.</td></tr><tr><td><strong>Max Products (Empty = unlimited)</strong></td><td>How many products the seller can list.</td></tr><tr><td><strong>Max Staff</strong></td><td>How many team members the seller can add. It starts at 1; clear it for no limit.</td></tr><tr><td><strong>Commission Value</strong></td><td>The commission percentage you take from sellers on this plan. It replaces the seller&#39;s own rate. Always enter a value; see <a href="./../payments/commission-management">Commission</a>.</td></tr><tr><td><strong>Is Featured</strong></td><td>Marks the plan with a star for sellers.</td></tr><tr><td><strong>Status</strong></td><td>Shows the plan to sellers. It is off on a new plan.</td></tr><tr><td><strong>Position</strong></td><td>The order the plan appears in. Enter 1 or more, and a different number for each plan.</td></tr><tr><td><strong>Allowed Product Types</strong></td><td>The kinds of product sellers on this plan can sell.</td></tr></tbody></table><p>You&#39;ll see <strong>Plan created successfully.</strong></p><h2 id="manage-plans" tabindex="-1">Manage plans <a class="header-anchor" href="#manage-plans" aria-label="Permalink to &quot;Manage plans&quot;">​</a></h2><p>The <strong>Plans</strong> list shows each plan&#39;s <strong>ID</strong>, <strong>Name</strong>, <strong>Code</strong>, <strong>Price</strong>, <strong>Billing Cycle</strong>, <strong>Status</strong> and <strong>Position</strong>, with icons to edit or delete it. To switch several plans on or off, tick them and use <strong>Select Action &gt;&gt; Update Status</strong>, or remove them with <strong>Select Action &gt;&gt; Delete</strong>.</p>',4)),s(n,{src:"/images/seller-subscription-management/plans-list.png",alt:"The Plans list"}),t[2]||(t[2]=e('<ul><li>Editing a plan doesn&#39;t change it for sellers who have already bought it.</li><li>A plan with active subscriptions can&#39;t be deleted. Deleting a plan cancels its pending subscriptions.</li></ul><h2 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Subscription Plans &gt;&gt; Subscription</strong> to see every plan sellers have bought, with the <strong>Seller</strong>, <strong>Plan</strong>, <strong>Payment</strong> method, <strong>Status</strong>, dates and <strong>Price</strong>.</p>',3)),s(n,{src:"/images/seller-subscription-management/subscriptions.png",alt:"The Subscriptions list"}),t[3]||(t[3]=e('<table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Waiting for you to approve because the seller paid offline, or a PayPal payment isn&#39;t finished.</td></tr><tr><td><strong>Active</strong></td><td>The plan is running.</td></tr><tr><td><strong>Expired</strong></td><td>The plan&#39;s end date has passed.</td></tr><tr><td><strong>Canceled</strong></td><td>You cancelled the plan, the seller cancelled a PayPal payment or bought another plan while this one was pending, or the plan was deleted.</td></tr></tbody></table><h3 id="approve-a-subscription" tabindex="-1">Approve a subscription <a class="header-anchor" href="#approve-a-subscription" aria-label="Permalink to &quot;Approve a subscription&quot;">​</a></h3><p>When a seller pays with a method that isn&#39;t PayPal, such as Money Transfer, the plan waits as <strong>Pending</strong>. Cash On Delivery isn&#39;t offered for plans.</p><ol><li>Go to <strong>Marketplace &gt;&gt; Subscription Plans &gt;&gt; Subscription</strong>.</li><li>Click the view icon on the pending subscription.</li><li>Check that you have received the payment.</li><li>Click <strong>Approve</strong>.</li></ol>',4)),s(n,{src:"/images/seller-subscription-management/view-subscription.png",alt:"A pending subscription with the Approve and Cancel buttons"}),t[4]||(t[4]=e('<p>To cancel a pending or active plan, click <strong>Cancel</strong>. To decide on several at once, tick them and use <strong>Select Action &gt;&gt; Update Status</strong>. A plan can&#39;t be approved while the seller already has an active plan for the same dates.</p><h2 id="what-happens-automatically" tabindex="-1">What happens automatically <a class="header-anchor" href="#what-happens-automatically" aria-label="Permalink to &quot;What happens automatically&quot;">​</a></h2><p>These run on the store&#39;s scheduler, so make sure it is running on your server:</p><ul><li>Sellers are emailed 9, 7, 3 and 1 days before their plan ends.</li><li>Plans past their end date are marked <strong>Expired</strong>.</li><li>Sellers&#39; account health is refreshed every day.</li></ul><p>When a plan expires without another one to follow, the seller can only reach their profile and the plans page, their products are hidden, their allowed product types are cleared, and their commission becomes 100% until they buy a new plan. See <a href="./choosing-a-plan#when-your-plan-ends">Choosing a Plan</a>.</p><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><p>The seller and the store admin both receive an email when a subscription is created, activated, cancelled or expires. Sellers also receive the reminder emails before their plan ends. No email is sent when a subscription is cancelled because the seller bought another plan, or because the plan was deleted.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>To give another admin access, tick <strong>Marketplace &gt;&gt; Subscription Plans</strong> in their role: <strong>Subscription Plans</strong> with <strong>Create</strong>, <strong>Edit</strong> and <strong>Delete</strong>, and <strong>Subscription</strong> with <strong>View</strong> and <strong>Edit</strong>.</p>',9))])}const f=a(i,[["render",d]]);export{b as __pageData,f as default};
